#!/usr/bin/env node
const path = require('path');
const cmd = process.argv[2];

// Git calls these two. They must print ONLY the file content to stdout.
if (cmd === 'clean' || cmd === 'smudge') {
  require('../lib/filter').run(cmd);
  return;
}

const { init } = require('../lib/init');

if (cmd === 'init') {
  const result = init(process.cwd());
  console.log(result.ok ? 'showscape: set up.' : 'showscape: skipped (' + result.reason + ')');
  return;
}

if (cmd === 'postinstall') {
  // INIT_CWD = the folder where the user ran "npm install"
  const dir = process.env.INIT_CWD;
  // Skip when installing inside our own package folder (development)
  if (!dir || path.resolve(dir) === path.resolve(__dirname, '..')) process.exit(0);
  try {
    init(dir);
  } catch (err) {
    console.error('showscape: setup failed, run "npx showscape init" later. ' + err.message);
  }
  process.exit(0); // never break someone's npm install
}

console.error('Usage: showscape init');
process.exit(1);
